dict(t='करी वाला मसूर का सूप',p='4',s='रेसिपी का 1/4 भाग',
i=['1 बड़ा चम्मच ऑलिव ऑयल','1/4 कप लाल प्याज़, कटा हुआ','1 बड़ा चम्मच लहसुन, बारीक कटा हुआ','1 बड़ा चम्मच ताज़ा अदरक, बारीक कटा हुआ','2 छोटे चम्मच करी पाउडर','1 छोटा चम्मच जीरा','1 छोटा चम्मच पिसा धनिया','1/8 छोटा चम्मच पिसी काली मिर्च','2/3 कप लाल मसूर*, धोई हुई','32 औंस बिना नमक डाला सब्जी स्टॉक','1 कप फ्रोज़न मटर','8 औंस सख़्त टोफू, टुकड़ों में कटा हुआ','सुझाव: आप टोफू की जगह','पका हुआ चिकन या टर्की इस्तेमाल कर सकते हैं।'],
st=['एक बड़े सॉसपैन में ऑलिव ऑयल को मध्यम आँच पर गरम करें। प्याज़, लहसुन और अदरक को भूनें। मसाले डालें और प्याज़ के पारदर्शी होने तक भूनते रहें।','जब प्याज़ नरम हो जाए, तो मसूर और सब्जी स्टॉक डालें। सूप को उबाल आने दें। आँच को धीमा करें और लगभग 30 मिनट पकाएँ।','सूप में मटर और टोफू डालें। 10 मिनट और धीमी आँच पर पकाएँ और परोसें।'],
h=['* मसूर में पोटैशियम अधिक होता है और इसे','संयम से खाना चाहिए',
'क्रॉनिक किडनी डिज़ीज़ (CKD) के शुरुआती चरण में, लोगों को आमतौर पर अपने खाए जाने वाले प्रोटीन की मात्रा कम करनी चाहिए, खासकर अधिक प्रोटीन वाले खाद्य पदार्थों से जैसे मांस में पाया जाने वाला पशु प्रोटीन। शोध से पता चला है कि रेड या प्रोसेस्ड मीट की जगह मेवे, फलियाँ-दालें और कम वसा वाले डेयरी उत्पाद लेने से CKD की प्रगति को धीमा करने में मदद मिल सकती है।\n\nबीन्स, मटर और मसूर जैसी फलियाँ और दालें प्रोटीन, जटिल कार्बोहाइड्रेट और आहार फाइबर के बेहतरीन स्रोत हैं और इनमें वसा कम होती है। इन्हें स्वास्थ्यप्रद माना जाता है क्योंकि ये हृदय स्वास्थ्य को बढ़ावा देती हैं, आंत्र नियमितता बनाए रखती हैं और रक्त शर्करा के स्तर को स्थिर रखने में मदद कर सकती हैं। इसके अतिरिक्त, ये आपको देर तक पेट भरा महसूस कराती हैं, जिससे आपको सोडियम और फॉस्फोरस से भरपूर अस्वास्थ्यकर नाश्ते खाने के प्रलोभन से बचने में मदद मिलती है।\n\nहालाँकि फलियों और दालों में पोटैशियम अधिक होता है, इसलिए CKD वाले या डायलिसिस करा रहे व्यक्तियों को इनका सेवन संयम से करना चाहिए। अपने रीनल डाइटीशियन से पूछें कि आपके आहार में फलियों और दालों की कितनी मात्रा आपके लिए सही है।'],
f=['2 मीट (मांस)','2 स्टार्च','1 कम पोटैशियम वाली सब्जी']),
dict(t='आइस्ड कॉफ़ी',p='1',s='1 पेय',
i=['1 बोतल किडनी के अनुकूल ओरल न्यूट्रिशनल सप्लीमेंट*, वैनिला (237 मि.ली.)','1 कप बर्फ़ के टुकड़े','1 छोटा चम्मच इंस्टेंट कॉफ़ी'],
st=['सभी सामग्री को ब्लेंडर में मिलाएँ। तुरंत परोसें। 2017-04-13 8:53 AM'],
h=['* किडनी के अनुकूल ओरल न्यूट्रिशनल सप्लीमेंट के बारे में अपने डॉक्टर, डाइटीशियन या फार्मासिस्ट से पूछें।',
'क्रॉनिक किडनी डिज़ीज़ (CKD) के निदान के साथ, सामान्य किडनी कार्य बाधित हो जाता है। इससे न केवल यह बदलता है कि आपकी किडनी कुछ पोषक तत्वों को कैसे छानती हैं, बल्कि यह आपके शरीर को चाहिए कैलोरी और प्रोटीन की मात्रा को भी प्रभावित करता है, जिससे आपको कुपोषण का अधिक जोखिम होता है। पर्याप्त नाश्ते और भोजन, साथ ही किडनी के अनुकूल ONS, CKD में आपकी पोषण स्थिति को बेहतर बनाने के पहले कदम हैं।\n\nONS पोषण से भरपूर होते हैं। कुछ पेय किडनी के मरीज़ों की ज़रूरतों को पूरा करने के लिए बनाए गए हैं और उनमें सोडियम, पोटैशियम और फॉस्फोरस सीमित होते हैं।\n\nनाश्ते या भोजन के विकल्प के रूप में ONS: यदि आप अपने पोषण लक्ष्यों को पूरा करने के लिए पर्याप्त कैलोरी और प्रोटीन नहीं खा रहे हैं, तो आपका डाइटीशियन या डॉक्टर नाश्ते या भोजन के विकल्प के रूप में ONS की सलाह दे सकता है। यदि आपका लक्ष्य स्वस्थ तरीके से वज़न घटाना है, तो यह किसी अस्वास्थ्यकर भोजन की जगह ले सकता है। यदि आपकी भूख कम है या आप नियमित रूप से दिन में 3 बार भोजन नहीं करते, तो किडनी के अनुकूल ONS छूटे हुए भोजन की जगह ले सकता है।\n\nअन्य रेसिपी में ONS: अपने भोजन और नाश्ते में विविधता जोड़ने के लिए ONS को प्रोटीन बार, मफिन, स्मूदी या मुख्य व्यंजनों के हिस्से के रूप में शामिल करें।'],
f=['2 मीट (मांस)','2 स्टार्च','2 फैट (वसा)']),
dict(t='समर चिकन ब्रेस्ट',p='4',s='रेसिपी का ¼ भाग',
i=['चार (4) 3 औंस के चिकन ब्रेस्ट','2 बड़े चम्मच ऑलिव ऑयल','2 बड़े चम्मच व्हाइट वाइन विनेगर','1 लहसुन की कली, बारीक कटी हुई','¼ कप ताज़ी तुलसी, बारीक कटी हुई','¼ कप पुदीना, बारीक कटा हुआ','¼ कप ऑलिव ऑयल','2 बड़े चम्मच व्हाइट वाइन विनेगर','1 लहसुन की कली, बारीक कटी हुई','¼ कप ताज़ी तुलसी, बारीक कटी हुई','¼ कप पुदीना, बारीक कटा हुआ'],
st=['मैरिनेड की सामग्री को एक बंद होने वाले प्लास्टिक बैग या ढक्कन वाले डिब्बे में मिलाएँ। चिकन ब्रेस्ट को मैरिनेड के मिश्रण में डालें, यह सुनिश्चित करते हुए कि वे मैरिनेड से अच्छी तरह ढके हों। 12 घंटे या रातभर फ्रिज में रखें।','मैरिनेट किए चिकन ब्रेस्ट को पकाने के लिए तैयार होने पर ग्रिल को तेज़ आँच पर गरम करें।','चिकन ब्रेस्ट को मैरिनेड से निकालें और जड़ी-बूटियाँ झाड़ दें (ग्रिल करते समय चिकन ब्रेस्ट पर बची जड़ी-बूटियाँ जल सकती हैं)। मैरिनेड फेंक दें।','ग्रिल का तापमान मध्यम करें, ग्रिल पर तेल लगाएँ और चिकन ब्रेस्ट को ग्रिल पर रखें। ढककर 7-8 मिनट ग्रिल करें। चिकन ब्रेस्ट को पलटें, ढकें और 7-8 मिनट और या आंतरिक तापमान 165°F पढ़ने तक ग्रिल करें।','ग्रिल किए हुए चिकन ब्रेस्ट को प्लेट में रखें, एल्युमिनियम फ़ॉइल से ढकें और प्राकृतिक रस को बाँधे रखने के लिए 10 मिनट रखा रहने दें।','चिकन को रखा रहने देते समय, एक छोटे कटोरे में ड्रेसिंग की सामग्री मिलाएँ।','चिकन ब्रेस्ट के स्लाइस काटें, उन्हें परोसने की प्लेट पर रखें और कटे हुए चिकन के ऊपर ड्रेसिंग डालें। ओवन/स्टोव विधि: ग्रिल नहीं है, कोई बात नहीं! ओवन को 350°F पर पहले से गरम करें। चिकन ब्रेस्ट को बेकिंग पेपर या एल्युमिनियम फ़ॉइल बिछी बेकिंग शीट पर रखें। 10 मिनट बेक करें, चिकन को पलटें, फिर 165°F का आंतरिक तापमान पहुँचने तक 10 मिनट और बेक करें। आप स्टोव पर ग्रिल पैन का भी उपयोग कर सकते हैं।'],
h=['जिन लोगों को CKD है और जो डायलिसिस पर नहीं हैं, वे चिकन की मात्रा घटाकर प्रोटीन की मात्रा कम करें',
'खाद्य लेबल पर न्यूट्रिशन फैक्ट्स हमें पैकेटबंद खाद्य पदार्थों के पोषक तत्वों के बारे में बताते हैं। उदाहरण के लिए, सोडियम, प्रोटीन और पोटैशियम किडनी रोग वाले लोगों के लिए नज़र रखने योग्य महत्वपूर्ण पोषक तत्व हैं, और अब हर लेबल पर सूचीबद्ध होते हैं। आप जो खाना पसंद करते हैं उसमें पोटैशियम की मात्रा समझने के लिए: 1. पोटैशियम योजक वाले खाद्य पदार्थों से बचने की कोशिश करें। ये ऐसे खाद्य पदार्थ हैं जिनकी सामग्री में \"potassium\" शब्द किसी अन्य शब्द के साथ सूचीबद्ध होता है (जैसे potassium chloride)। 2. सर्विंग का आकार निर्धारित करें। कई बार केवल एक सर्विंग लेने से कुछ कम से मध्यम पोटैशियम वाले खाद्य पदार्थ आपके आहार में फिट हो सकते हैं। 3. इसके बाद, न्यूट्रिशन फैक्ट्स के नीचे बताए गए खनिजों और विटामिनों के साथ पोटैशियम खोजें। पोटैशियम की मात्रा प्रति सर्विंग मिलीग्राम में और प्रतिशत (%) दैनिक मान (DV) के साथ सूचीबद्ध होती है। • ध्यान दें कि % DV कुल 4,700 मिलीग्राम पोटैशियम पर आधारित है। यह वह मात्रा है जो औसत वयस्क को एक दिन में लेनी चाहिए। हालाँकि, यह क्रॉनिक किडनी डिज़ीज़ वाले कई लोगों के लिए अनुशंसित मात्रा से बहुत अधिक है। इसलिए, यदि आप कम पोटैशियम वाले आहार पर हैं, तो % DV आप पर लागू नहीं होता और यह बहुत अधिक हो सकता है। आपके लिए कौन सी मात्रा सुरक्षित है, यह जानने के लिए अपनी स्वास्थ्य सेवा टीम या किडनी रोग में विशेषज्ञता रखने वाले रजिस्टर्ड डाइटीशियन न्यूट्रिशनिस्ट के साथ काम करें। • सामान्य नियम के रूप में, पोटैशियम के 5% DV से कम वाले खाद्य पदार्थ चुनने का लक्ष्य रखें। समान उत्पादों की साथ-साथ तुलना करने के लिए पोटैशियम के % DV का उपयोग करें।'],
f=['4 लीन प्रोटीन']),
